2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const areNeighbors = (cell: Cell, other: Cell): boolean => {
7	  const [x, y] = cell;
8	  const [otherX, otherY] = other;
9	  const isTouching = Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;
10	  return isTouching && !isSameCell(cell, other);
11	};
12	
13	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
14	  liveCells.filter((liveCell) => areNeighbors(cell, liveCell)).length;
15	
16	// Fewer than 2 neighbors is underpopulation, more than 3 is overpopulation;
17	// both are death. Only this band survives.
18	const MIN_NEIGHBORS_TO_SURVIVE = 2;
19	const MAX_NEIGHBORS_TO_SURVIVE = 3;
20	
21	const survives = (liveNeighborCount: number): boolean =>
22	  liveNeighborCount >= MIN_NEIGHBORS_TO_SURVIVE &&
23	  liveNeighborCount <= MAX_NEIGHBORS_TO_SURVIVE;
24	
25	const NEIGHBORS_TO_BE_BORN = 3;
26	
27	const isBorn = (liveNeighborCount: number): boolean =>
28	  liveNeighborCount === NEIGHBORS_TO_BE_BORN;
29	
30	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
31	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
32	
33	// Only cells touching a live cell can change state, so the rest of the
34	// infinite grid never needs to be examined.
35	const cellsToEvaluate = (liveCells: Cell[]): Cell[] => {
36	  const byCoordinate = new Map<string, Cell>();
37	  for (const [x, y] of liveCells) {
38	    for (let dx = -1; dx <= 1; dx++) {
39	      for (let dy = -1; dy <= 1; dy++) {
40	        byCoordinate.set(`${x + dx},${y + dy}`, [x + dx, y + dy]);
41	      }
42	    }
43	  }
44	  return [...byCoordinate.values()];
45	};
46	
47	export function nextGeneration(liveCells: Cell[]): Cell[] {
48	  return cellsToEvaluate(liveCells).filter((cell) => {
49	    const liveNeighborCount = countLiveNeighbors(cell, liveCells);
50	    return isAlive(cell, liveCells)
51	      ? survives(liveNeighborCount)
52	      : isBorn(liveNeighborCount);
53	  });
54	}
