4	describe("Game of Life - nextGeneration", () => {
5	  it("returns an empty grid for an empty grid — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	
9	  it("Rule 1 (underpopulation): a single live cell with 0 neighbors dies — [(0,0)] → []", () => {
10	    expect(nextGeneration([[0, 0]])).toEqual([]);
11	  });
12	
13	  it("Rule 1 (underpopulation): two adjacent live cells each with 1 neighbor die — [(0,1), (1,1)] → []", () => {
14	    expect(
15	      nextGeneration([
16	        [0, 1],
17	        [1, 1],
18	      ]),
19	    ).toEqual([]);
20	  });
21	
22	  it("Rule 2 (survival): a live cell with 2 live neighbors lives on — blinker [(0,0), (0,1), (0,2)] keeps (0,1) alive", () => {
23	    expect(
24	      nextGeneration([
25	        [0, 0],
26	        [0, 1],
27	        [0, 2],
28	      ]),
29	    ).toContainEqual([0, 1]);
30	  });
31	
32	  // NOTE: the spec's Rule 2 illustration (### / ... / .#. → .#. / .#. / ...) is
33	  // internally inconsistent: in its own Gen 0 drawing the cell (1,1) is dead and
34	  // has 4 neighbors, not the 3 the prose claims, and the drawn Gen 1 is not what
